import { useEffect, useState } from 'react';
import { Chart } from 'primereact/chart';
import { Dropdown } from 'primereact/dropdown';
import { Calendar } from 'primereact/calendar';
import { getMetrics } from '../services/api';

const metricLabels = {
  temperature: 'Температура (°C)',
  humidity: 'Вологість (%)',
  light: 'Освітлення (lx)',
  pressure: 'Тиск (гПа)',
  air_quality: 'Якість повітря (PM2.5, мкг/м³)',
  co2: 'CO₂ (ppm)',
  wind_speed: 'Швидкість вітру (м/с)',
  noise_level: 'Рівень шуму (дБ)',
  battery: 'Заряд батареї (%)'
};

export default function MetricsChart({ deviceId }) {
  const [metricsByType, setMetricsByType] = useState({});
  const [selectedMetricTypes, setSelectedMetricTypes] = useState([]);
  const [dateRange, setDateRange] = useState([null, null]);

  const metricOptions = Object.keys(metricLabels).map((type) => ({
    label: metricLabels[type],
    value: type,
  }));

  useEffect(() => {
    if (!deviceId) return;

    const params = { deviceId };
    if (selectedMetricTypes.length > 0) {
      params.metric_types = selectedMetricTypes.join(',');
    }
    if (dateRange[0] && dateRange[1]) {
      params.start_time = dateRange[0].toISOString();
      params.end_time = dateRange[1].toISOString();
    }

    getMetrics(params).then((metrics) => {
      const grouped = {};

      for (const metric of metrics) {
        const { type, value, timestamp } = metric;
        if (!grouped[type]) grouped[type] = { labels: [], data: [] };

        grouped[type].labels.push(new Date(timestamp).toLocaleTimeString());
        grouped[type].data.push(value);
      }

      setMetricsByType(grouped);
    });
  }, [deviceId, selectedMetricTypes, dateRange]);

  if (!deviceId) {
    return <div className="card">Виберіть пристрій для перегляду метрик</div>;
  }

  return (
    <div className="grid">
      <div className="col-12">
        <div className="card">
          <h3>Фільтри</h3>
          <Dropdown
            value={selectedMetricTypes}
            options={metricOptions}
            onChange={(e) => setSelectedMetricTypes(e.value)}
            placeholder="Виберіть типи метрик"
            className="w-full mb-3"
            multiple
          />
          <Calendar
            value={dateRange}
            onChange={(e) => setDateRange(e.value)}
            selectionMode="range"
            placeholder="Виберіть діапазон дат"
            className="w-full"
            showTime
          />
        </div>
      </div>
      {Object.entries(metricsByType)
        .filter(([type]) => selectedMetricTypes.length === 0 || selectedMetricTypes.includes(type))
        .map(([type, { labels, data }]) => (
          <div className="col-12 md:col-6" key={type}>
            <div className="card">
              <h4>{metricLabels[type] || type}</h4>
              <Chart
                type="line"
                data={{
                  labels,
                  datasets: [{
                    label: metricLabels[type] || type,
                    data,
                    borderColor: '#42A5F5',
                    fill: false,
                  }],
                }}
                options={{
                  responsive: true,
                  plugins: {
                    legend: { position: 'top' },
                  },
                }}
              />
            </div>
          </div>
        ))}
    </div>
  );
}
